@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #E63946;
  --red-dark: #B91C2C;
  --red-glow: rgba(230, 57, 70, 0.3);
  --bg: #111111;
  --bg-card: #1A1A1A;
  --bg-elevated: #222222;
  --text: #FFFFFF;
  --text-muted: #999999;
  --text-dim: #666666;
  --border: #333333;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }

/* ─── TOP BAR ─── */
.top-bar {
  background: var(--red);
  color: white;
  text-align: center;
  padding: 0.6rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.top-bar a {
  font-weight: 600;
  text-decoration: underline;
  margin-left: 0.5rem;
}
.top-bar a:hover { opacity: 0.85; }

/* ─── NAVBAR ─── */
.navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 0;
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text);
}
.nav-logo span { color: var(--red); }

.nav-links { display: flex; gap: 2rem; align-items: center; }
.nav-links a {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--text); }

.nav-cta {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}
.nav-cta .btn-sm {
  padding: 0.5rem 1.2rem;
  font-size: 0.75rem;
  border-radius: 2px;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  transition: var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  top: 70px;
  background: rgba(17, 17, 17, 0.98);
  backdrop-filter: blur(20px);
  z-index: 999;
  padding: 2rem;
  flex-direction: column;
  gap: 1.5rem;
}
.mobile-menu.open { display: flex; }
.mobile-menu a {
  font-family: var(--font-display);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  transition: color var(--transition);
}
.mobile-menu a:hover { color: var(--text); }

/* ─── BUTTONS ─── */
.btn {
  display: inline-block;
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border: none;
  transition: all var(--transition);
  text-align: center;
}
.btn-primary {
  background: var(--red);
  color: white;
  padding: 1rem 2.5rem;
  font-size: 1rem;
  border-radius: 2px;
}
.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px var(--red-glow);
}
.btn-outline {
  background: transparent;
  color: white;
  padding: 1rem 2.5rem;
  font-size: 1rem;
  border: 2px solid white;
  border-radius: 2px;
}
.btn-outline:hover {
  background: white;
  color: var(--bg);
  transform: translateY(-2px);
}
.btn-sm {
  padding: 0.5rem 1.2rem;
  font-size: 0.8rem;
}
.btn-ghost {
  background: transparent;
  color: var(--red);
  padding: 0.5rem 0;
  border: none;
  font-size: 0.85rem;
  letter-spacing: 0.08em;
}
.btn-ghost:hover { color: white; }

/* ─── HERO ─── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(17,17,17,0.3) 0%, rgba(17,17,17,0.85) 70%, var(--bg) 100%);
  z-index: 1;
}
.hero-bg-image {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: 0.5;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 2rem;
}
.hero-content h1 {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 7vw, 5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 0.02em;
  margin-bottom: 1.5rem;
}
.hero-content h1 .highlight { color: var(--red); }
.hero-content p {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--text-muted);
  margin-bottom: 2.5rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}
.hero-buttons { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

.hero-sm { min-height: 50vh; }
.hero-sm .hero-content h1 { font-size: clamp(2rem, 5vw, 3.5rem); }

/* ─── SECTIONS ─── */
section { padding: 6rem 0; }
section.alt-bg { background: var(--bg-card); }

.section-label {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--red);
  margin-bottom: 1rem;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.1;
  margin-bottom: 1.5rem;
}
.section-subtitle {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 650px;
  line-height: 1.7;
}
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ─── TWO WAYS CARDS ─── */
.two-ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}
.way-card {
  position: relative;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  padding: 3rem 2rem;
  transition: all var(--transition);
}
.way-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.way-card h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  text-transform: uppercase;
  margin-bottom: 1rem;
}
.way-card p {
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}
.way-card-icon {
  width: 48px;
  height: 48px;
  background: var(--red);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}

/* ─── STUDIO EXPERIENCE ─── */
.studio-section {
  position: relative;
  padding: 8rem 0;
  text-align: center;
  overflow: hidden;
}
.studio-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, var(--bg) 0%, rgba(230,57,70,0.08) 50%, var(--bg) 100%);
}
.studio-section .container { position: relative; z-index: 1; }

/* ─── FREE TRIAL ─── */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 5rem 0;
}
.free-trial h2 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 2rem;
}
.free-trial .btn {
  background: white;
  color: var(--red);
  font-size: 1.1rem;
  padding: 1.1rem 3rem;
}
.free-trial .btn:hover {
  background: var(--bg);
  color: white;
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

/* ─── CAROUSEL ─── */
.carousel-section { padding: 6rem 0; overflow: hidden; }
.carousel-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
  border-radius: 4px;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  position: relative;
  overflow: hidden;
}
.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.carousel-slide .slide-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 2rem;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
}
.carousel-slide .slide-overlay p {
  font-family: var(--font-display);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;
  color: white;
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: all var(--transition);
}
.carousel-btn:hover { background: var(--red); border-color: var(--red); }
.carousel-btn.prev { left: 1rem; }
.carousel-btn.next { right: 1rem; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: none;
  background: var(--border);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active { background: var(--red); transform: scale(1.2); }

/* ─── NEWSLETTER ─── */
.newsletter {
  padding: 5rem 0;
  border-top: 1px solid var(--border);
}
.newsletter-inner {
  max-width: 550px;
  margin: 0 auto;
  text-align: center;
}
.newsletter h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}
.newsletter p {
  color: var(--text-muted);
  margin-bottom: 2rem;
  font-size: 0.95rem;
}
.newsletter-form {
  display: flex;
  gap: 0;
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.newsletter-form:focus-within { border-color: var(--red); }
.newsletter-form input {
  flex: 1;
  padding: 1rem 1.25rem;
  background: var(--bg-card);
  border: none;
  color: white;
  font-size: 0.95rem;
  outline: none;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form button {
  background: var(--red);
  color: white;
  border: none;
  padding: 1rem 2rem;
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.85rem;
  transition: background var(--transition);
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-feedback {
  margin-top: 0.75rem;
  font-size: 0.85rem;
  min-height: 1.5em;
}
.newsletter-feedback.success { color: #4ade80; }
.newsletter-feedback.error { color: var(--red); }

/* ─── FOOTER ─── */
.footer {
  background: #0A0A0A;
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2.5rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text);
  margin-bottom: 1.25rem;
}
.footer-col a {
  display: block;
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 0.6rem;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--red); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  color: var(--text-dim);
  font-size: 0.8rem;
}
.country-select {
  background: transparent;
  color: var(--text-dim);
  border: 1px solid var(--border);
  padding: 0.4rem 0.8rem;
  font-size: 0.8rem;
  border-radius: 2px;
  cursor: pointer;
}
.country-select:focus { border-color: var(--red); outline: none; }

/* ─── WORKOUT PAGE ─── */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
}
.schedule-table th,
.schedule-table td {
  padding: 1.1rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
.schedule-table th {
  font-family: var(--font-display);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td { font-size: 0.95rem; }
.schedule-table tr:hover td { background: rgba(230,57,70,0.05); }
.schedule-table .day {
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ─── TOGGLE ─── */
.toggle-container {
  display: flex;
  justify-content: center;
  margin-bottom: 3rem;
}
.toggle-group {
  display: inline-flex;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
}
.toggle-btn {
  padding: 1rem 2.5rem;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: all var(--transition);
  cursor: pointer;
}
.toggle-btn.active {
  background: var(--red);
  color: white;
}
.toggle-btn:hover:not(.active) { color: white; }

.toggle-content {
  display: none;
  animation: fadeUp 0.4s ease-out;
}
.toggle-content.active { display: block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.toggle-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}
.toggle-panel-text h3 {
  font-family: var(--font-display);
  font-size: 2rem;
  text-transform: uppercase;
  margin-bottom: 1rem;
}
.toggle-panel-text p { color: var(--text-muted); line-height: 1.8; }
.toggle-panel-image {
  aspect-ratio: 4/3;
  background: var(--bg-elevated);
  border-radius: 4px;
  overflow: hidden;
}
.toggle-panel-image img { width: 100%; height: 100%; object-fit: cover; }

/* ─── INSTRUCTOR PAGE ─── */
.filter-bar {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 3rem;
}
.filter-btn {
  padding: 0.6rem 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 2px;
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: all var(--transition);
  cursor: pointer;
}
.filter-btn:hover { border-color: var(--red); color: white; }
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: white;
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 2rem;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.3);
}
.instructor-card-img {
  aspect-ratio: 1;
  background: var(--bg-elevated);
  overflow: hidden;
  position: relative;
}
.instructor-card-img img { width: 100%; height: 100%; object-fit: cover; }
.instructor-card-img .initials {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 3rem;
  font-weight: 700;
  color: var(--red);
  background: linear-gradient(135deg, var(--bg-card), var(--bg-elevated));
}
.instructor-card-body { padding: 1.5rem; }
.instructor-card-body h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  text-transform: uppercase;
  margin-bottom: 0.3rem;
}
.instructor-card-body .location {
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 1rem;
}
.instructor-card-body .btn-ghost { font-size: 0.8rem; }

.instructor-card.hidden {
  display: none;
}

/* ─── FAQ ACCORDION ─── */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  padding: 1.5rem 0;
  background: transparent;
  border: none;
  color: white;
  font-family: var(--font-display);
  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question .icon {
  font-size: 1.5rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 1rem;
}
.faq-item.open .faq-question .icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner {
  padding: 0 0 1.5rem;
  color: var(--text-muted);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ─── DIGITAL FEATURES ─── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2.5rem 2rem;
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}
.feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(230,57,70,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--red);
  font-size: 1.3rem;
}
.feature-card h3 {
  font-family: var(--font-display);
  font-size: 1.15rem;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}
.feature-card p { color: var(--text-muted); font-size: 0.9rem; line-height: 1.7; }

/* ─── CTA BAND ─── */
.cta-band {
  padding: 4rem 0;
  text-align: center;
  background: var(--bg-card);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.cta-band h2 {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  text-transform: uppercase;
  margin-bottom: 2rem;
}

/* ─── SCROLL REVEAL ─── */
.reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}
.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .hamburger { display: flex; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  section { padding: 4rem 0; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .toggle-panel { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
  .hero { min-height: 70vh; }
  .hero-sm { min-height: 40vh; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { padding: 1rem; }
}

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #E63946;
  --red-dark: #B91C2C;
  --red-glow: rgba(230, 57, 70, 0.3);
  --bg: #111111;
  --bg-card: #1A1A1A;
  --bg-elevated: #222222;
  --text: #FFFFFF;
  --text-muted: #999999;
  --text-dim: #666666;
  --border: #333333;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }

/* ─── TOP BAR ─── */
.top-bar {
  background: var(--red);
  color: white;
  text-align: center;
  padding: 0.6rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.top-bar a {
  font-weight: 600;
  text-decoration: underline;
  margin-left: 0.5rem;
}
.top-bar a:hover { opacity: 0.85; }

/* ─── NAVBAR ─── */
.navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 0;
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text);
}
.nav-logo span { color: var(--red); }

.nav-links { display: flex; gap: 2rem; align-items: center; }
.nav-links a {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--text); }

.nav-cta {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}
.nav-cta .btn-sm {
  padding: 0.5rem 1.2rem;
  font-size: 0.75rem;
  border-radius: 2px;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  transition: var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  top: 70px;
  background: rgba(17, 17, 17, 0.98);
  backdrop-filter: blur(20px);
  z-index: 999;
  padding: 2rem;
  flex-direction: column;
  gap: 1.5rem;
}
.mobile-menu.open { display: flex; }
.mobile-menu a {
  font-family: var(--font-display);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  transition: color var(--transition);
}
.mobile-menu a:hover { color: var(--text); }

/* ─── BUTTONS ─── */
.btn {
  display: inline-block;
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border: none;
  transition: all var(--transition);
  text-align: center;
}
.btn-primary {
  background: var(--red);
  color: white;
  padding: 1rem 2.5rem;
  font-size: 1rem;
  border-radius: 2px;
}
.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px var(--red-glow);
}
.btn-outline {
  background: transparent;
  color: white;
  padding: 1rem 2.5rem;
  font-size: 1rem;
  border: 2px solid white;
  border-radius: 2px;
}
.btn-outline:hover {
  background: white;
  color: var(--bg);
  transform: translateY(-2px);
}
.btn-sm {
  padding: 0.5rem 1.2rem;
  font-size: 0.8rem;
}
.btn-ghost {
  background: transparent;
  color: var(--red);
  padding: 0.5rem 0;
  border: none;
  font-size: 0.85rem;
  letter-spacing: 0.08em;
}
.btn-ghost:hover { color: white; }

/* ─── HERO ─── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(17,17,17,0.3) 0%, rgba(17,17,17,0.85) 70%, var(--bg) 100%);
  z-index: 1;
}
.hero-bg-image {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: 0.5;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 2rem;
}
.hero-content h1 {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 7vw, 5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 0.02em;
  margin-bottom: 1.5rem;
}
.hero-content h1 .highlight { color: var(--red); }
.hero-content p {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--text-muted);
  margin-bottom: 2.5rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}
.hero-buttons { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

.hero-sm { min-height: 50vh; }
.hero-sm .hero-content h1 { font-size: clamp(2rem, 5vw, 3.5rem); }

/* ─── SECTIONS ─── */
section { padding: 6rem 0; }
section.alt-bg { background: var(--bg-card); }

.section-label {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--red);
  margin-bottom: 1rem;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.1;
  margin-bottom: 1.5rem;
}
.section-subtitle {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 650px;
  line-height: 1.7;
}
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ─── TWO WAYS CARDS ─── */
.two-ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}
.way-card {
  position: relative;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  padding: 3rem 2rem;
  transition: all var(--transition);
}
.way-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.way-card h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  text-transform: uppercase;
  margin-bottom: 1rem;
}
.way-card p {
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}
.way-card-icon {
  width: 48px;
  height: 48px;
  background: var(--red);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}

/* ─── STUDIO EXPERIENCE ─── */
.studio-section {
  position: relative;
  padding: 8rem 0;
  text-align: center;
  overflow: hidden;
}
.studio-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, var(--bg) 0%, rgba(230,57,70,0.08) 50%, var(--bg) 100%);
}
.studio-section .container { position: relative; z-index: 1; }

/* ─── FREE TRIAL ─── */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 5rem 0;
}
.free-trial h2 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 2rem;
}
.free-trial .btn {
  background: white;
  color: var(--red);
  font-size: 1.1rem;
  padding: 1.1rem 3rem;
}
.free-trial .btn:hover {
  background: var(--bg);
  color: white;
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

/* ─── CAROUSEL ─── */
.carousel-section { padding: 6rem 0; overflow: hidden; }
.carousel-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
  border-radius: 4px;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  position: relative;
  overflow: hidden;
}
.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.carousel-slide .slide-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 2rem;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
}
.carousel-slide .slide-overlay p {
  font-family: var(--font-display);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;
  color: white;
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: all var(--transition);
}
.carousel-btn:hover { background: var(--red); border-color: var(--red); }
.carousel-btn.prev { left: 1rem; }
.carousel-btn.next { right: 1rem; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: none;
  background: var(--border);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active { background: var(--red); transform: scale(1.2); }

/* ─── NEWSLETTER ─── */
.newsletter {
  padding: 5rem 0;
  border-top: 1px solid var(--border);
}
.newsletter-inner {
  max-width: 550px;
  margin: 0 auto;
  text-align: center;
}
.newsletter h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}
.newsletter p {
  color: var(--text-muted);
  margin-bottom: 2rem;
  font-size: 0.95rem;
}
.newsletter-form {
  display: flex;
  gap: 0;
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.newsletter-form:focus-within { border-color: var(--red); }
.newsletter-form input {
  flex: 1;
  padding: 1rem 1.25rem;
  background: var(--bg-card);
  border: none;
  color: white;
  font-size: 0.95rem;
  outline: none;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form button {
  background: var(--red);
  color: white;
  border: none;
  padding: 1rem 2rem;
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.85rem;
  transition: background var(--transition);
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-feedback {
  margin-top: 0.75rem;
  font-size: 0.85rem;
  min-height: 1.5em;
}
.newsletter-feedback.success { color: #4ade80; }
.newsletter-feedback.error { color: var(--red); }

/* ─── FOOTER ─── */
.footer {
  background: #0A0A0A;
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2.5rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text);
  margin-bottom: 1.25rem;
}
.footer-col a {
  display: block;
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 0.6rem;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--red); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  color: var(--text-dim);
  font-size: 0.8rem;
}
.country-select {
  background: transparent;
  color: var(--text-dim);
  border: 1px solid var(--border);
  padding: 0.4rem 0.8rem;
  font-size: 0.8rem;
  border-radius: 2px;
  cursor: pointer;
}
.country-select:focus { border-color: var(--red); outline: none; }

/* ─── WORKOUT PAGE ─── */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
}
.schedule-table th,
.schedule-table td {
  padding: 1.1rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
.schedule-table th {
  font-family: var(--font-display);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td { font-size: 0.95rem; }
.schedule-table tr:hover td { background: rgba(230,57,70,0.05); }
.schedule-table .day {
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ─── TOGGLE ─── */
.toggle-container {
  display: flex;
  justify-content: center;
  margin-bottom: 3rem;
}
.toggle-group {
  display: inline-flex;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
}
.toggle-btn {
  padding: 1rem 2.5rem;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: all var(--transition);
  cursor: pointer;
}
.toggle-btn.active {
  background: var(--red);
  color: white;
}
.toggle-btn:hover:not(.active) { color: white; }

.toggle-content {
  display: none;
  animation: fadeUp 0.4s ease-out;
}
.toggle-content.active { display: block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.toggle-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}
.toggle-panel-text h3 {
  font-family: var(--font-display);
  font-size: 2rem;
  text-transform: uppercase;
  margin-bottom: 1rem;
}
.toggle-panel-text p { color: var(--text-muted); line-height: 1.8; }
.toggle-panel-image {
  aspect-ratio: 4/3;
  background: var(--bg-elevated);
  border-radius: 4px;
  overflow: hidden;
}
.toggle-panel-image img { width: 100%; height: 100%; object-fit: cover; }

/* ─── INSTRUCTOR PAGE ─── */
.filter-bar {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 3rem;
}
.filter-btn {
  padding: 0.6rem 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 2px;
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: all var(--transition);
  cursor: pointer;
}
.filter-btn:hover { border-color: var(--red); color: white; }
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: white;
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 2rem;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.3);
}
.instructor-card-img {
  aspect-ratio: 1;
  background: var(--bg-elevated);
  overflow: hidden;
  position: relative;
}
.instructor-card-img img { width: 100%; height: 100%; object-fit: cover; }
.instructor-card-img .initials {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 3rem;
  font-weight: 700;
  color: var(--red);
  background: linear-gradient(135deg, var(--bg-card), var(--bg-elevated));
}
.instructor-card-body { padding: 1.5rem; }
.instructor-card-body h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  text-transform: uppercase;
  margin-bottom: 0.3rem;
}
.instructor-card-body .location {
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 1rem;
}
.instructor-card-body .btn-ghost { font-size: 0.8rem; }

.instructor-card.hidden {
  display: none;
}

/* ─── FAQ ACCORDION ─── */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  padding: 1.5rem 0;
  background: transparent;
  border: none;
  color: white;
  font-family: var(--font-display);
  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question .icon {
  font-size: 1.5rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 1rem;
}
.faq-item.open .faq-question .icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner {
  padding: 0 0 1.5rem;
  color: var(--text-muted);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ─── DIGITAL FEATURES ─── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2.5rem 2rem;
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}
.feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(230,57,70,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--red);
  font-size: 1.3rem;
}
.feature-card h3 {
  font-family: var(--font-display);
  font-size: 1.15rem;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}
.feature-card p { color: var(--text-muted); font-size: 0.9rem; line-height: 1.7; }

/* ─── CTA BAND ─── */
.cta-band {
  padding: 4rem 0;
  text-align: center;
  background: var(--bg-card);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.cta-band h2 {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  text-transform: uppercase;
  margin-bottom: 2rem;
}

/* ─── SCROLL REVEAL ─── */
.reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}
.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .hamburger { display: flex; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  section { padding: 4rem 0; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .toggle-panel { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
  .hero { min-height: 70vh; }
  .hero-sm { min-height: 40vh; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { padding: 1rem; }
}

raw_arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #E63946;
  --red-dark: #B91C2C;
  --red-glow: rgba(230, 57, 70, 0.3);
  --bg: #111111;
  --bg-card: #1A1A1A;
  --bg-elevated: #222222;
  --text: #FFFFFF;
  --text-muted: #999999;
  --text-dim: #666666;
  --border: #333333;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }

/* ─── TOP BAR ─── */
.top-bar {
  background: var(--red);
  color: white;
  text-align: center;
  padding: 0.6rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.top-bar a {
  font-weight: 600;
  text-decoration: underline;
  margin-left: 0.5rem;
}
.top-bar a:hover { opacity: 0.85; }

/* ─── NAVBAR ─── */
.navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 0;
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text);
}
.nav-logo span { color: var(--red); }

.nav-links { display: flex; gap: 2rem; align-items: center; }
.nav-links a {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--text); }

.nav-cta {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}
.nav-cta .btn-sm {
  padding: 0.5rem 1.2rem;
  font-size: 0.75rem;
  border-radius: 2px;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  transition: var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  top: 70px;
  background: rgba(17, 17, 17, 0.98);
  backdrop-filter: blur(20px);
  z-index: 999;
  padding: 2rem;
  flex-direction: column;
  gap: 1.5rem;
}
.mobile-menu.open { display: flex; }
.mobile-menu a {
  font-family: var(--font-display);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  transition: color var(--transition);
}
.mobile-menu a:hover { color: var(--text); }

/* ─── BUTTONS ─── */
.btn {
  display: inline-block;
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border: none;
  transition: all var(--transition);
  text-align: center;
}
.btn-primary {
  background: var(--red);
  color: white;
  padding: 1rem 2.5rem;
  font-size: 1rem;
  border-radius: 2px;
}
.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px var(--red-glow);
}
.btn-outline {
  background: transparent;
  color: white;
  padding: 1rem 2.5rem;
  font-size: 1rem;
  border: 2px solid white;
  border-radius: 2px;
}
.btn-outline:hover {
  background: white;
  color: var(--bg);
  transform: translateY(-2px);
}
.btn-sm {
  padding: 0.5rem 1.2rem;
  font-size: 0.8rem;
}
.btn-ghost {
  background: transparent;
  color: var(--red);
  padding: 0.5rem 0;
  border: none;
  font-size: 0.85rem;
  letter-spacing: 0.08em;
}
.btn-ghost:hover { color: white; }

/* ─── HERO ─── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(17,17,17,0.3) 0%, rgba(17,17,17,0.85) 70%, var(--bg) 100%);
  z-index: 1;
}
.hero-bg-image {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: 0.5;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 2rem;
}
.hero-content h1 {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 7vw, 5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 0.02em;
  margin-bottom: 1.5rem;
}
.hero-content h1 .highlight { color: var(--red); }
.hero-content p {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--text-muted);
  margin-bottom: 2.5rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}
.hero-buttons { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

.hero-sm { min-height: 50vh; }
.hero-sm .hero-content h1 { font-size: clamp(2rem, 5vw, 3.5rem); }

/* ─── SECTIONS ─── */
section { padding: 6rem 0; }
section.alt-bg { background: var(--bg-card); }

.section-label {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--red);
  margin-bottom: 1rem;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.1;
  margin-bottom: 1.5rem;
}
.section-subtitle {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 650px;
  line-height: 1.7;
}
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ─── TWO WAYS CARDS ─── */
.two-ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}
.way-card {
  position: relative;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  padding: 3rem 2rem;
  transition: all var(--transition);
}
.way-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.way-card h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  text-transform: uppercase;
  margin-bottom: 1rem;
}
.way-card p {
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}
.way-card-icon {
  width: 48px;
  height: 48px;
  background: var(--red);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}

/* ─── STUDIO EXPERIENCE ─── */
.studio-section {
  position: relative;
  padding: 8rem 0;
  text-align: center;
  overflow: hidden;
}
.studio-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, var(--bg) 0%, rgba(230,57,70,0.08) 50%, var(--bg) 100%);
}
.studio-section .container { position: relative; z-index: 1; }

/* ─── FREE TRIAL ─── */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 5rem 0;
}
.free-trial h2 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 2rem;
}
.free-trial .btn {
  background: white;
  color: var(--red);
  font-size: 1.1rem;
  padding: 1.1rem 3rem;
}
.free-trial .btn:hover {
  background: var(--bg);
  color: white;
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

/* ─── CAROUSEL ─── */
.carousel-section { padding: 6rem 0; overflow: hidden; }
.carousel-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
  border-radius: 4px;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  position: relative;
  overflow: hidden;
}
.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.carousel-slide .slide-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 2rem;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
}
.carousel-slide .slide-overlay p {
  font-family: var(--font-display);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;
  color: white;
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: all var(--transition);
}
.carousel-btn:hover { background: var(--red); border-color: var(--red); }
.carousel-btn.prev { left: 1rem; }
.carousel-btn.next { right: 1rem; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: none;
  background: var(--border);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active { background: var(--red); transform: scale(1.2); }

/* ─── NEWSLETTER ─── */
.newsletter {
  padding: 5rem 0;
  border-top: 1px solid var(--border);
}
.newsletter-inner {
  max-width: 550px;
  margin: 0 auto;
  text-align: center;
}
.newsletter h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}
.newsletter p {
  color: var(--text-muted);
  margin-bottom: 2rem;
  font-size: 0.95rem;
}
.newsletter-form {
  display: flex;
  gap: 0;
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.newsletter-form:focus-within { border-color: var(--red); }
.newsletter-form input {
  flex: 1;
  padding: 1rem 1.25rem;
  background: var(--bg-card);
  border: none;
  color: white;
  font-size: 0.95rem;
  outline: none;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form button {
  background: var(--red);
  color: white;
  border: none;
  padding: 1rem 2rem;
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.85rem;
  transition: background var(--transition);
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-feedback {
  margin-top: 0.75rem;
  font-size: 0.85rem;
  min-height: 1.5em;
}
.newsletter-feedback.success { color: #4ade80; }
.newsletter-feedback.error { color: var(--red); }

/* ─── FOOTER ─── */
.footer {
  background: #0A0A0A;
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2.5rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text);
  margin-bottom: 1.25rem;
}
.footer-col a {
  display: block;
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 0.6rem;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--red); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  color: var(--text-dim);
  font-size: 0.8rem;
}
.country-select {
  background: transparent;
  color: var(--text-dim);
  border: 1px solid var(--border);
  padding: 0.4rem 0.8rem;
  font-size: 0.8rem;
  border-radius: 2px;
  cursor: pointer;
}
.country-select:focus { border-color: var(--red); outline: none; }

/* ─── WORKOUT PAGE ─── */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
}
.schedule-table th,
.schedule-table td {
  padding: 1.1rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
.schedule-table th {
  font-family: var(--font-display);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td { font-size: 0.95rem; }
.schedule-table tr:hover td { background: rgba(230,57,70,0.05); }
.schedule-table .day {
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ─── TOGGLE ─── */
.toggle-container {
  display: flex;
  justify-content: center;
  margin-bottom: 3rem;
}
.toggle-group {
  display: inline-flex;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
}
.toggle-btn {
  padding: 1rem 2.5rem;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: all var(--transition);
  cursor: pointer;
}
.toggle-btn.active {
  background: var(--red);
  color: white;
}
.toggle-btn:hover:not(.active) { color: white; }

.toggle-content {
  display: none;
  animation: fadeUp 0.4s ease-out;
}
.toggle-content.active { display: block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.toggle-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}
.toggle-panel-text h3 {
  font-family: var(--font-display);
  font-size: 2rem;
  text-transform: uppercase;
  margin-bottom: 1rem;
}
.toggle-panel-text p { color: var(--text-muted); line-height: 1.8; }
.toggle-panel-image {
  aspect-ratio: 4/3;
  background: var(--bg-elevated);
  border-radius: 4px;
  overflow: hidden;
}
.toggle-panel-image img { width: 100%; height: 100%; object-fit: cover; }

/* ─── INSTRUCTOR PAGE ─── */
.filter-bar {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 3rem;
}
.filter-btn {
  padding: 0.6rem 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 2px;
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: all var(--transition);
  cursor: pointer;
}
.filter-btn:hover { border-color: var(--red); color: white; }
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: white;
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 2rem;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.3);
}
.instructor-card-img {
  aspect-ratio: 1;
  background: var(--bg-elevated);
  overflow: hidden;
  position: relative;
}
.instructor-card-img img { width: 100%; height: 100%; object-fit: cover; }
.instructor-card-img .initials {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 3rem;
  font-weight: 700;
  color: var(--red);
  background: linear-gradient(135deg, var(--bg-card), var(--bg-elevated));
}
.instructor-card-body { padding: 1.5rem; }
.instructor-card-body h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  text-transform: uppercase;
  margin-bottom: 0.3rem;
}
.instructor-card-body .location {
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 1rem;
}
.instructor-card-body .btn-ghost { font-size: 0.8rem; }

.instructor-card.hidden {
  display: none;
}

/* ─── FAQ ACCORDION ─── */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  padding: 1.5rem 0;
  background: transparent;
  border: none;
  color: white;
  font-family: var(--font-display);
  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question .icon {
  font-size: 1.5rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 1rem;
}
.faq-item.open .faq-question .icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner {
  padding: 0 0 1.5rem;
  color: var(--text-muted);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ─── DIGITAL FEATURES ─── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2.5rem 2rem;
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}
.feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(230,57,70,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--red);
  font-size: 1.3rem;
}
.feature-card h3 {
  font-family: var(--font-display);
  font-size: 1.15rem;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}
.feature-card p { color: var(--text-muted); font-size: 0.9rem; line-height: 1.7; }

/* ─── CTA BAND ─── */
.cta-band {
  padding: 4rem 0;
  text-align: center;
  background: var(--bg-card);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.cta-band h2 {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  text-transform: uppercase;
  margin-bottom: 2rem;
}

/* ─── SCROLL REVEAL ─── */
.reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}
.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .hamburger { display: flex; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  section { padding: 4rem 0; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .toggle-panel { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
  .hero { min-height: 70vh; }
  .hero-sm { min-height: 40vh; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { padding: 1rem; }
}

